ield }}]" value="{{ $value }}">@endforeach</div>@endforeach</div><p id="empty-items" class="empty-table" @if(old('items')) hidden @endif>No items added yet.</p>@error('items')<p class="form-error">{{ $message }}</p>@enderror</div></div></div></x-card>
