<script>document.addEventListener('DOMContentLoaded',()=>{const clients=@json($clientOptions),clientSelect=document.querySelector('#client_id'),preview=document.querySelector('#waybill_preview');const updatePreview=()=>{const client=clients.find(entry=>String(entry.id)===clientSelect.value);preview.value=client?`${client.prefix||`${client.client_code}-`}${String(Number(client.last_value)+1).padStart(8,'0')}`:'Select a client to generate';};clientSelect.addEventListener('change',updatePreview);updatePreview();const list=document.querySelector('#waybill-items'),empty=document.querySelector('#empty-items'),count=document.querySelector('#item-count');let index=list.children.length;const itemFields=['reference','description','sku','length','width','height','weight','remarks'];const refreshItems=()=>{const total=list.children.length;empty.hidden=total>0;count.textContent=`${total} item${total===1?'':'s'}`;};document.querySelector('#add-waybill-item').addEventListener('click',()=>{const values=Object.fromEntries(itemFields.map(field=>[field,document.querySelector(`#new_item_${field}`).value.trim()]));if(!values.description){document.querySelector('#new_item_description').focus();return;}const details=[values.reference,values.sku].filter(Boolean).map(value=>escapeHtml(value)).join(' · ');const hidden=itemFields.map(field=>`<input type="hidden" name="items[${index}][item_${field}]" value="${escapeHtml(values[field])}">`).join('');list.insertAdjacentHTML('beforeend',`<div class="waybill-item" data-index="${index}"><div><strong>${escapeHtml(values.description)}</strong><small>${details}</small></div><div class="row-actions"><button type="button" class="table-action table-action-danger remove-waybill-item">Remove</button></div>${hidden}</div>`);index++;itemFields.forEach(field=>document.querySelector(`#new_item_${field}`).value='');refreshItems();});list.addEventListener('click',event=>{if(!event.target.classList.contains('remove-waybill-item'))return;event.target.closest('.waybill-item').remove();refreshItems();});const escapeHtml=value=>String(value).replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[character]));refreshItems();const sellers=@json($sellerOptions);const name=document.querySelector('#seller_name');const fields=['full_address','province','city','barangay','contact_number','email','building_type'];let selectedSeller=null;name.addEventListener('input',()=>{const match=sellers.find(seller=>seller.client_name.toLocaleLowerCase()===name.value.trim().toLocaleLowerCase());if(match){fields.forEach(field=>{document.querySelector(`#seller_${field}`).value=match[field]??'';});selectedSeller=match.client_name;return;}if(selectedSeller){fields.forEach(field=>{document.querySelector(`#seller_${field}`).value='';});selectedSeller=null;}});});</script>
